function getNationalNumber(input) {
  if (typeof input !== "string") {
    return null;
  }

  const value = input.replace(/[\s().-]/g, "");

  if (!/^\+?\d+$/.test(value)) {
    return null;
  }

  let nationalNumber;
  let hasCountryCode = false;

  if (value.startsWith("+")) {
    if (!value.startsWith("+234")) {
      return null;
    }

    nationalNumber = value.slice(4);
    hasCountryCode = true;
  } else if (value.startsWith("00234")) {
    nationalNumber = value.slice(5);
    hasCountryCode = true;
  } else if (value.startsWith("234")) {
    nationalNumber = value.slice(3);
    hasCountryCode = true;
  } else if (value.startsWith("0") && !value.startsWith("00")) {
    nationalNumber = value.slice(1);
  } else {
    nationalNumber = value;
  }

  if (hasCountryCode) {
    if (nationalNumber.startsWith("00")) {
      return null;
    }

    if (nationalNumber.startsWith("0")) {
      nationalNumber = nationalNumber.slice(1);
    }
  }

  return /^[789][01]\d{8}$/.test(nationalNumber)
    ? nationalNumber
    : null;
}

export function normalizeNigerianPhone(input) {
  const nationalNumber = getNationalNumber(input);

  return nationalNumber === null ? null : `+234${nationalNumber}`;
}

export function formatNigerianPhone(input) {
  const nationalNumber = getNationalNumber(input);

  if (nationalNumber === null) {
    return null;
  }

  return `0${nationalNumber.slice(0, 3)} ${nationalNumber.slice(3, 6)} ${nationalNumber.slice(6)}`;
}
